from pathlib import Path

p=Path('src/index.html')
html=p.read_text(encoding='utf-8')
if 'PHASE2 BETA5 FIX3' not in html:
    raise SystemExit('beta.5.3 marker not found')
marker='\n\n    updateBackButton();'
if marker not in html:
    raise SystemExit('fix4 insertion marker not found')

fix=r'''  // PHASE2 BETA5 FIX4 — simplified Class Reports + next-level progression guard/admin override.
  let p2v54ClassReportView='home';
  let p2v54BatchFilter={course:'',batch:'',year:'',status:'All',search:''};
  let p2v54OverridePending=null;

  function p2v54EnsureStyle(){
    if($('p2v54Style'))return;
    const style=document.createElement('style');style.id='p2v54Style';style.textContent=`
      .p2v54-report-home{display:grid;grid-template-columns:repeat(2,minmax(260px,1fr));gap:16px}.p2v54-report-choice{background:#fff;border:1px solid #cfdeed;border-radius:15px;padding:22px;text-align:left;cursor:pointer;min-height:118px;color:#103d80}.p2v54-report-choice:hover{border-color:#7ea8d7;box-shadow:0 8px 24px rgba(15,61,125,.08)}.p2v54-report-choice strong{font-size:20px;display:block;margin-bottom:7px}.p2v54-report-choice small{font-size:13px;color:#62778f;line-height:1.45}
      .p2v54-banner{background:#123f7d;color:#fff;border-radius:16px;border-bottom:4px solid #f0b429;padding:22px 26px;display:flex;align-items:center;justify-content:space-between;gap:18px;margin-bottom:18px}.p2v54-banner h2{margin:0 0 5px;font-size:26px}.p2v54-banner p{margin:0;color:#e8f1fb}.p2v54-banner-actions{display:flex;gap:10px;flex-wrap:wrap}.p2v54-banner .btn.secondary{background:#fff;color:#123f7d;border-color:#fff}
      .p2v54-filterbar{display:grid;grid-template-columns:1.15fr 1.15fr .8fr .85fr 1.35fr;gap:12px;background:#fff;border:1px solid #d8e4f0;border-radius:14px;padding:16px;margin-bottom:14px}.p2v54-filterbar label{display:block;font-size:11px;font-weight:900;color:#17385f;margin-bottom:6px;text-transform:uppercase}.p2v54-filterbar select,.p2v54-filterbar input{width:100%;height:42px;border:1px solid #c9d9e9;border-radius:9px;padding:0 11px;background:#fff;color:#17385f}
      .p2v54-kpis{display:grid;grid-template-columns:repeat(6,minmax(120px,1fr));gap:10px;margin-bottom:14px}.p2v54-kpi{border:1px solid #d9e5f1;border-radius:13px;padding:14px;background:#f7fbff}.p2v54-kpi.green{background:#eefaf3}.p2v54-kpi.red{background:#fff0f0}.p2v54-kpi.blue{background:#eef5ff}.p2v54-kpi.amber{background:#fff8e9}.p2v54-kpi span{font-size:11px;text-transform:uppercase;font-weight:900;color:#49637d;display:block}.p2v54-kpi b{font-size:25px;color:#102f60;display:block;margin-top:4px}
      .p2v54-table-card{background:#fff;border:1px solid #d8e4f0;border-radius:14px;padding:14px;overflow:hidden}.p2v54-table-head{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:10px}.p2v54-table-head h3{margin:0;color:#123f7d}.p2v54-table-wrap{overflow:auto;border:1px solid #dce6f0;border-radius:10px}.p2v54-table{width:100%;border-collapse:collapse;min-width:980px}.p2v54-table th{background:#edf5fc;color:#17385f;font-size:12px;text-align:left;padding:10px;border-bottom:1px solid #d7e2ed}.p2v54-table td{padding:9px 10px;border-bottom:1px solid #e5edf5;color:#254564;font-size:13px}.p2v54-table tr:last-child td{border-bottom:0}.p2v54-pill{display:inline-block;border-radius:999px;padding:4px 9px;font-size:11px;font-weight:900}.p2v54-pill.green{background:#dff6e8;color:#137044}.p2v54-pill.red{background:#ffe4e4;color:#b92727}.p2v54-pill.blue{background:#e4efff;color:#1d5fad}.p2v54-pill.gray{background:#edf0f4;color:#5e6c7b}.p2v54-pill.amber{background:#fff1c9;color:#8a6200}
      .p2v54-progression{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:14px}.p2v54-prog-card{border:1px solid #d9e5f1;border-radius:13px;padding:14px;background:#fff}.p2v54-prog-card b{font-size:24px;color:#123f7d}.p2v54-prog-card span{display:block;color:#526d87;font-size:12px;margin-top:3px}
      .p2v54-list-card{background:#fff;border:1px solid #d8e4f0;border-radius:14px;padding:16px}.p2v54-list-card h3{margin:0 0 12px;color:#123f7d}.p2v54-override-note{font-size:11px;color:#8a6200;font-weight:800}
      #p2v54OverrideModal .review-note{min-height:18px}
      @media(max-width:1150px){.p2v54-filterbar{grid-template-columns:repeat(2,1fr)}.p2v54-kpis{grid-template-columns:repeat(3,1fr)}}@media(max-width:760px){.p2v54-report-home{grid-template-columns:1fr}.p2v54-filterbar{grid-template-columns:1fr}.p2v54-kpis,.p2v54-progression{grid-template-columns:1fr 1fr}.p2v54-banner{align-items:flex-start;flex-direction:column}}
    `;document.head.appendChild(style)
  }
  p2v54EnsureStyle();

  function p2v54EnsureOverrideModal(){
    if($('p2v54OverrideModal'))return;
    document.body.insertAdjacentHTML('beforeend',`<div id="p2v54OverrideModal" class="modal-backdrop"><form id="p2v54OverrideForm" class="modal" style="width:min(480px,100%)"><div class="modal-head"><h3>Admin approval required</h3><button id="p2v54OverrideClose" type="button" class="x">×</button></div><div id="p2v54OverrideText" class="security-warning" style="margin-bottom:14px"></div><div class="field full"><label>ADMINISTRATOR PASSWORD *</label><input id="p2v54OverridePassword" type="password" autocomplete="current-password" required></div><div id="p2v54OverrideError" class="review-note" style="margin-top:10px"></div><div class="actions" style="margin-top:16px"><button class="btn" type="submit">Approve enrollment</button><button id="p2v54OverrideCancel" class="btn ghost" type="button">Cancel</button></div></form></div>`);
    const close=()=>{$('p2v54OverrideModal').classList.remove('open');$('p2v54OverridePassword').value='';$('p2v54OverrideError').textContent='';p2v54OverridePending=null};
    $('p2v54OverrideClose').onclick=close;$('p2v54OverrideCancel').onclick=close;
    $('p2v54OverrideForm').onsubmit=async ev=>{ev.preventDefault();const pending=p2v54OverridePending,record=v51SecurityRecord(),err=$('p2v54OverrideError');err.textContent='';if(!pending)return close();if(!record){err.textContent='Create an administrator password in Settings first.';return}try{const hash=await v51PasswordHash($('p2v54OverridePassword').value,record.salt);if(hash!==record.hash){err.textContent='Incorrect administrator password.';return}const action=pending.action,reason=pending.reason;close();p2v54AdminOverrideReason=reason;action();p2v54AdminOverrideReason='';}catch(ex){err.textContent=ex.message||'Password verification failed.'}}
  }
  p2v54EnsureOverrideModal();
  let p2v54AdminOverrideReason='';

  function p2v54TargetProgressionLevel(b){const c=p2CourseForBatch(b);return c?.category==='Progression'?c.name:(p2Levels.includes(b?.level)?b.level:'')}
  function p2v54StudentFromEnrollForm(){const hidden=$('p2EnrollStudentId')?.value||'',name=$('p2cEnrollName')?.value.trim()||'',mobile=normMobile($('p2cEnrollMobile')?.value||'');return state.students.find(s=>s.id===hidden)||state.students.find(s=>mobile&&normMobile(s.mobile)===mobile)||state.students.find(s=>name&&normName(s.name)===normName(name))||null}
  function p2v54ProgressionCheck(student,b){
    const level=p2v54TargetProgressionLevel(b),idx=p2Levels.indexOf(level);if(idx<=0)return{ok:true,reason:''};
    const prev=p2Levels[idx-1];if(!student)return{ok:false,reason:`No completed ${prev} record was found for this person.`};
    const completed=state.classEnrollments.some(e=>e.studentId===student.id&&e.level===prev&&e.outcome==='Completed');
    return completed?{ok:true,reason:''}:{ok:false,reason:`${student.name} has not completed ${prev}. Enrollment in ${level} requires administrator approval.`}
  }

  const p2v54CreateEnrollmentBase=p2CreateEnrollment;
  p2CreateEnrollment=function(studentId,batchId){const en=p2v54CreateEnrollmentBase(studentId,batchId);if(en&&p2v54AdminOverrideReason){en.adminOverride=true;en.adminOverrideReason=p2v54AdminOverrideReason;en.adminOverrideAt=new Date().toISOString()}return en};

  const p2v54EnrollSubmitBase=$('p2EnrollForm')?.onsubmit;
  if($('p2EnrollForm')&&p2v54EnrollSubmitBase){
    $('p2EnrollForm').onsubmit=function(ev){
      ev.preventDefault();const b=p2ActiveBatch();if(!b)return p2v54EnrollSubmitBase.call(this,{preventDefault(){}});
      const check=p2v54ProgressionCheck(p2v54StudentFromEnrollForm(),b);
      if(check.ok)return p2v54EnrollSubmitBase.call(this,{preventDefault(){}});
      p2v54OverridePending={reason:check.reason,action:()=>{p2v54EnrollSubmitBase.call($('p2EnrollForm'),{preventDefault(){}});const recent=state.classEnrollments.filter(e=>e.batchId===b.id&&e.adminOverride).at(-1);if(recent)save()}};
      $('p2v54OverrideText').textContent=check.reason;$('p2v54OverrideError').textContent='';$('p2v54OverrideModal').classList.add('open');setTimeout(()=>$('p2v54OverridePassword').focus(),0)
    }
  }

  function p2v54NextStatus(en,b){
    const level=p2v54TargetProgressionLevel(b),idx=p2Levels.indexOf(level),person=p2v5Person(en);
    if(idx<0)return{key:'Not Eligible',label:'Not Eligible',cls:'gray'};
    if(level==='Level 4'){
      const s=en.studentId?p2FindStudent(en.studentId):null,received=!!(s&&(s.kriyabanId||s.kriyaDate||s.kriyaYear));
      return received?{key:'Joined',label:'Kriya Received',cls:'blue'}:{key:'Not Eligible',label:'Acharya Decision',cls:'gray'}
    }
    const next=p2Levels[idx+1];if(!next)return{key:'Not Eligible',label:'Not Eligible',cls:'gray'};
    const joined=!!en.studentId&&state.classEnrollments.some(x=>x.studentId===en.studentId&&x.level===next);
    if(joined)return{key:'Joined',label:`Joined ${next}`,cls:'blue'};
    if(en.outcome==='Completed')return{key:'Eligible',label:`Eligible for ${next}`,cls:'green'};
    return{key:'Not Eligible',label:'Not Eligible',cls:'gray'}
  }
  function p2v54BatchRows(b){return state.classEnrollments.filter(e=>e.batchId===b.id).map(en=>{const p=p2v5Person(en),a=p2v53AttendanceSummary(b,en),st=p2v54NextStatus(en,b);return{en,p,a,st}}).sort((x,y)=>x.p.name.localeCompare(y.p.name,undefined,{sensitivity:'base'}))}
  function p2v54FilteredBatchRows(b){let rows=p2v54BatchRows(b);if(p2v54BatchFilter.status!=='All')rows=rows.filter(r=>r.st.key===p2v54BatchFilter.status);const q=p2v54BatchFilter.search.trim().toLowerCase();if(q)rows=rows.filter(r=>`${r.p.name} ${r.p.mobile}`.toLowerCase().includes(q));return rows}

  function p2v54ClassReportHome(panel){
    p2v54ClassReportView='home';
    panel.innerHTML=`<div class="card-head"><div><h3>Class Reports</h3><div class="card-sub">Choose what you want to view. Reports open on screen first; export is available inside each report.</div></div></div><div class="p2v54-report-home"><button id="p2v54BatchReport" class="p2v54-report-choice"><strong>01 · Batch Report</strong><small>Roster, attendance totals, outcome, payment and next-level status for one selected batch.</small></button><button id="p2v54StudentList" class="p2v54-report-choice"><strong>02 · Student Progress List</strong><small>Complete list of all students and their current class progression.</small></button><button id="p2v54Followup" class="p2v54-report-choice"><strong>03 · Follow-up & Outreach</strong><small>Students who need next-level follow-up, repeat classes or Kriya follow-up.</small></button><button id="p2v54Annual" class="p2v54-report-choice"><strong>04 · Annual Class Summary</strong><small>Year-wise class batches, enrolments and completions.</small></button></div>`;
    $('p2v54BatchReport').onclick=()=>p2v54OpenBatchReport(panel);$('p2v54StudentList').onclick=()=>p2v54OpenStudentList(panel);$('p2v54Followup').onclick=()=>p2v54OpenFollowup(panel);$('p2v54Annual').onclick=()=>p2v54OpenAnnual(panel)
  }

  function p2v54BatchCandidates(){let list=state.classBatches.slice().sort((a,z)=>String(z.start||'').localeCompare(String(a.start||'')));if(p2v54BatchFilter.course)list=list.filter(b=>String(b.courseId||p2CourseName(b))===p2v54BatchFilter.course);if(p2v54BatchFilter.year)list=list.filter(b=>String(p2BatchYear(b))===p2v54BatchFilter.year);return list}
  function p2v54NormalizeBatchFilter(){
    const all=state.classBatches.slice().sort((a,z)=>String(z.start||'').localeCompare(String(a.start||'')));if(!all.length)return null;
    let current=state.classBatches.find(b=>b.id===p2v54BatchFilter.batch)||all[0];if(!p2v54BatchFilter.course)p2v54BatchFilter.course=String(current.courseId||p2CourseName(current));if(!p2v54BatchFilter.year)p2v54BatchFilter.year=String(p2BatchYear(current));let candidates=p2v54BatchCandidates();if(!candidates.length){p2v54BatchFilter.course='';p2v54BatchFilter.year='';candidates=all}if(!candidates.some(b=>b.id===p2v54BatchFilter.batch))p2v54BatchFilter.batch=candidates[0].id;return state.classBatches.find(b=>b.id===p2v54BatchFilter.batch)||candidates[0]
  }
  function p2v54OpenBatchReport(panel){p2v54ClassReportView='batch';const b=p2v54NormalizeBatchFilter();if(!b){panel.innerHTML=`<button id="p2v54BackHome" class="btn secondary">← Back to Class Reports</button><div class="p2-empty" style="margin-top:14px">No class batches yet.</div>`;$('p2v54BackHome').onclick=()=>p2v54ClassReportHome(panel);return}p2v54RenderBatchReport(panel,b)}
  function p2v54RenderBatchReport(panel,b){
    const allRows=p2v54BatchRows(b),rows=p2v54FilteredBatchRows(b),courses=[...new Map(state.courseTypes.map(c=>[String(c.id||c.name),c])).values()],years=[...new Set(state.classBatches.map(x=>String(p2BatchYear(x))).filter(Boolean))].sort().reverse(),batches=p2v54BatchCandidates();
    const completed=allRows.filter(r=>r.en.outcome==='Completed').length,withdraw=allRows.filter(r=>/withdraw/i.test(r.en.outcome||'')).length,incomplete=allRows.filter(r=>r.en.outcome&&r.en.outcome!=='Completed'&&!/withdraw/i.test(r.en.outcome)).length,paid=allRows.filter(r=>r.en.paymentStatus==='Paid').length,eligible=allRows.filter(r=>r.st.key==='Eligible').length,joined=allRows.filter(r=>r.st.key==='Joined').length,notEligible=allRows.filter(r=>r.st.key==='Not Eligible').length;
    panel.innerHTML=`<div class="p2v54-banner"><div><h2>Batch Report</h2><p>View roster, attendance, outcomes, payment and progression for a selected class batch.</p></div><div class="p2v54-banner-actions"><button id="p2v54BackHome" class="btn secondary">← Back to Reports</button><button id="p2v54ExportBatch" class="btn">Export Excel</button></div></div><div class="p2v54-filterbar"><div><label>Course</label><select id="p2v54Course"><option value="">All Courses</option>${courses.map(c=>`<option value="${esc(String(c.id||c.name))}" ${String(c.id||c.name)===p2v54BatchFilter.course?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div><label>Batch</label><select id="p2v54Batch">${batches.map(x=>`<option value="${x.id}" ${x.id===b.id?'selected':''}>${esc(x.name)} · ${esc(p2CourseName(x))}</option>`).join('')}</select></div><div><label>Year</label><select id="p2v54Year"><option value="">All Years</option>${years.map(y=>`<option ${y===p2v54BatchFilter.year?'selected':''}>${esc(y)}</option>`).join('')}</select></div><div><label>Status</label><select id="p2v54Status">${['All','Joined','Eligible','Not Eligible'].map(s=>`<option ${s===p2v54BatchFilter.status?'selected':''}>${s}</option>`).join('')}</select></div><div><label>Search name or mobile</label><input id="p2v54Search" value="${esc(p2v54BatchFilter.search)}" placeholder="Search by name or mobile..."></div></div><div class="p2v54-kpis"><div class="p2v54-kpi blue"><span>Total Students</span><b>${allRows.length}</b></div><div class="p2v54-kpi green"><span>Completed</span><b>${completed}</b></div><div class="p2v54-kpi amber"><span>Incomplete</span><b>${incomplete}</b></div><div class="p2v54-kpi red"><span>Withdrawn</span><b>${withdraw}</b></div><div class="p2v54-kpi blue"><span>Sessions</span><b>${p2v5ValidDates(b).length}</b></div><div class="p2v54-kpi green"><span>Paid / Unpaid</span><b>${paid} / ${allRows.length-paid}</b></div></div><div class="p2v54-table-card"><div class="p2v54-table-head"><h3>Student List (${rows.length})</h3>${p2v53ActuallyEnded(b)?'<button id="p2v54EditEnded" class="btn secondary small">Edit Ended Batch</button>':''}</div><div class="p2v54-table-wrap"><table class="p2v54-table"><thead><tr><th>#</th><th>Name</th><th>Mobile</th><th>Sessions Attended / Total</th><th>Attendance %</th><th>Outcome</th><th>Payment</th><th>Next Level Status</th><th>Notes</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td>${i+1}</td><td><strong>${esc(r.p.name)}</strong>${r.en.adminOverride?'<div class="p2v54-override-note">Admin Override</div>':''}</td><td>${esc(r.p.mobile||'—')}</td><td>${r.a.present} / ${r.a.total}</td><td>${r.a.pct}%</td><td><span class="p2v54-pill ${r.en.outcome==='Completed'?'green':/withdraw/i.test(r.en.outcome||'')?'red':'amber'}">${esc(r.en.outcome||'Enrolled')}</span></td><td><span class="p2v54-pill ${r.en.paymentStatus==='Paid'?'green':'red'}">${r.en.paymentStatus==='Paid'?'Paid':'Unpaid'}</span></td><td><span class="p2v54-pill ${r.st.cls}">${esc(r.st.label)}</span></td><td>${r.en.adminOverride?esc(r.en.adminOverrideReason||'Admin override used'):'—'}</td></tr>`).join('')||'<tr><td colspan="9">No students match this filter.</td></tr>'}</tbody></table></div></div><div class="p2v54-progression"><div class="p2v54-prog-card"><b>${joined}</b><span>Joined next level</span></div><div class="p2v54-prog-card"><b>${eligible}</b><span>Eligible for next level</span></div><div class="p2v54-prog-card"><b>${notEligible}</b><span>Not eligible</span></div></div>`;
    $('p2v54BackHome').onclick=()=>p2v54ClassReportHome(panel);if($('p2v54EditEnded'))$('p2v54EditEnded').onclick=()=>{state.activeClassBatchId=b.id;save();switchPage('classWorkspace');p2v53EditingEnded.add(b.id);p2RenderClassWorkspace()};
    $('p2v54Course').onchange=()=>{p2v54BatchFilter.course=$('p2v54Course').value;p2v54BatchFilter.batch='';p2v54OpenBatchReport(panel)};$('p2v54Year').onchange=()=>{p2v54BatchFilter.year=$('p2v54Year').value;p2v54BatchFilter.batch='';p2v54OpenBatchReport(panel)};$('p2v54Batch').onchange=()=>{p2v54BatchFilter.batch=$('p2v54Batch').value;p2v54OpenBatchReport(panel)};$('p2v54Status').onchange=()=>{p2v54BatchFilter.status=$('p2v54Status').value;p2v54OpenBatchReport(panel)};$('p2v54Search').oninput=()=>{p2v54BatchFilter.search=$('p2v54Search').value;const pos=$('p2v54Search').selectionStart;p2v54RenderBatchReport(panel,b);setTimeout(()=>{const s=$('p2v54Search');if(s){s.focus();s.setSelectionRange(pos,pos)}},0)};
    $('p2v54ExportBatch').onclick=()=>v51RequireAdmin(()=>{const filtered=p2v54FilteredBatchRows(b).map(r=>({Name:r.p.name,Mobile:r.p.mobile||'',Course:p2CourseName(b),Batch:b.name,Year:p2BatchYear(b),Sessions_Attended:r.a.present,Total_Sessions:r.a.total,Attendance_Percent:r.a.pct,Outcome:r.en.outcome||'Enrolled',Payment:r.en.paymentStatus==='Paid'?'Paid':'Unpaid',Next_Level_Status:r.st.key,Progression:r.st.label,Admin_Override:r.en.adminOverride?'Yes':'No'}));p2Csv(filtered,`Ananda_${p2CourseName(b).replaceAll(' ','_')}_${b.name.replaceAll(' ','_')}_Batch_Report.csv`)},'export the filtered Batch Report')
  }

  function p2v54OpenStudentList(panel){p2v54ClassReportView='students';const rows=state.students.slice().sort((a,b)=>a.name.localeCompare(b.name,undefined,{sensitivity:'base'})).map(s=>{const es=p2StudentEnrollments(s.id),completed=es.filter(e=>e.outcome==='Completed'),last=completed.at(-1),lastBatch=last&&state.classBatches.find(b=>b.id===last.batchId);return{s,stage:p2CurrentStage(s),last,lastBatch}});panel.innerHTML=`<div class="p2v54-banner"><div><h2>Student Progress List</h2><p>Complete student list with current progression and most recent completed class.</p></div><div class="p2v54-banner-actions"><button id="p2v54BackHome" class="btn secondary">← Back to Reports</button><button id="p2v54ExportList" class="btn">Export Excel</button></div></div><div class="p2v54-list-card"><div class="p2v54-table-wrap"><table class="p2v54-table"><thead><tr><th>#</th><th>Name</th><th>Mobile</th><th>Current Stage</th><th>Last Completed</th><th>Last Batch</th><th>Kriya</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td>${i+1}</td><td>${esc(r.s.name)}</td><td>${esc(r.s.mobile||'')}</td><td>${esc(r.stage)}</td><td>${esc(r.last?.level||'—')}</td><td>${esc(r.lastBatch?.name||'—')}</td><td>${r.s.kriyabanId||r.s.kriyaDate||r.s.kriyaYear?'Received':'—'}</td></tr>`).join('')}</tbody></table></div></div>`;$('p2v54BackHome').onclick=()=>p2v54ClassReportHome(panel);$('p2v54ExportList').onclick=()=>v51RequireAdmin(()=>p2Csv(rows.map(r=>({Name:r.s.name,Mobile:r.s.mobile||'',Current_Stage:r.stage,Last_Completed:r.last?.level||'',Last_Batch:r.lastBatch?.name||'',Kriya:r.s.kriyabanId||r.s.kriyaDate||r.s.kriyaYear?'Received':''})),'Ananda_Student_Progress_List.csv'),'export the Student Progress List')}

  function p2v54OpenFollowup(panel){p2v54ClassReportView='followup';const rows=[];state.students.forEach(s=>{p2Levels.slice(0,3).forEach(level=>{const completed=p2StudentEnrollments(s.id).some(e=>e.level===level&&e.outcome==='Completed'),next=p2NextLevel(level),joined=p2StudentEnrollments(s.id).some(e=>e.level===next);if(completed&&!joined)rows.push({s,from:level,next,status:'Eligible — not yet joined'})});p2Levels.forEach(level=>{const attempts=p2StudentEnrollments(s.id).filter(e=>e.level===level);if(attempts.length&&!attempts.some(e=>e.outcome==='Completed'))rows.push({s,from:level,next:level,status:'Repeat / incomplete'})});const l4=p2StudentEnrollments(s.id).some(e=>e.level==='Level 4'&&e.outcome==='Completed');if(l4&&!(s.kriyabanId||s.kriyaDate||s.kriyaYear))rows.push({s,from:'Level 4',next:'Kriya',status:'Acharya / Kriya follow-up'})});rows.sort((a,b)=>a.s.name.localeCompare(b.s.name,undefined,{sensitivity:'base'}));panel.innerHTML=`<div class="p2v54-banner"><div><h2>Follow-up & Outreach</h2><p>Students needing progression, repeat-class or Kriya follow-up.</p></div><div class="p2v54-banner-actions"><button id="p2v54BackHome" class="btn secondary">← Back to Reports</button><button id="p2v54ExportFollow" class="btn">Export Excel</button></div></div><div class="p2v54-list-card"><div class="p2v54-table-wrap"><table class="p2v54-table"><thead><tr><th>#</th><th>Name</th><th>Mobile</th><th>From</th><th>Next</th><th>Follow-up Reason</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td>${i+1}</td><td>${esc(r.s.name)}</td><td>${esc(r.s.mobile||'')}</td><td>${esc(r.from)}</td><td>${esc(r.next)}</td><td>${esc(r.status)}</td></tr>`).join('')||'<tr><td colspan="6">No follow-up records.</td></tr>'}</tbody></table></div></div>`;$('p2v54BackHome').onclick=()=>p2v54ClassReportHome(panel);$('p2v54ExportFollow').onclick=()=>v51RequireAdmin(()=>p2Csv(rows.map(r=>({Name:r.s.name,Mobile:r.s.mobile||'',From:r.from,Next:r.next,Status:r.status})),'Ananda_Followup_Outreach.csv'),'export Follow-up & Outreach')}

  function p2v54OpenAnnual(panel){p2v54ClassReportView='annual';const rows=[];const years=[...new Set(state.classBatches.map(b=>String(p2BatchYear(b))).filter(Boolean))].sort().reverse();years.forEach(y=>state.courseTypes.forEach(c=>{const bs=state.classBatches.filter(b=>String(p2BatchYear(b))===y&&b.courseId===c.id);if(!bs.length)return;const ids=new Set(bs.map(b=>b.id)),es=state.classEnrollments.filter(e=>ids.has(e.batchId));rows.push({Year:y,Course:c.name,Batches:bs.length,Enrolments:es.length,Completed:es.filter(e=>e.outcome==='Completed').length,Incomplete:es.filter(e=>e.outcome&&e.outcome!=='Completed'&&!/withdraw/i.test(e.outcome)).length,Withdrawn:es.filter(e=>/withdraw/i.test(e.outcome||'')).length})}));panel.innerHTML=`<div class="p2v54-banner"><div><h2>Annual Class Summary</h2><p>Year-wise course, batch and completion totals.</p></div><div class="p2v54-banner-actions"><button id="p2v54BackHome" class="btn secondary">← Back to Reports</button><button id="p2v54ExportAnnual" class="btn">Export Excel</button></div></div><div class="p2v54-list-card"><div class="p2v54-table-wrap"><table class="p2v54-table"><thead><tr><th>Year</th><th>Course</th><th>Batches</th><th>Enrolments</th><th>Completed</th><th>Incomplete</th><th>Withdrawn</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.Year}</td><td>${esc(r.Course)}</td><td>${r.Batches}</td><td>${r.Enrolments}</td><td>${r.Completed}</td><td>${r.Incomplete}</td><td>${r.Withdrawn}</td></tr>`).join('')||'<tr><td colspan="7">No annual class records.</td></tr>'}</tbody></table></div></div>`;$('p2v54BackHome').onclick=()=>p2v54ClassReportHome(panel);$('p2v54ExportAnnual').onclick=()=>v51RequireAdmin(()=>p2Csv(rows,'Ananda_Annual_Class_Summary.csv'),'export the Annual Class Summary')}

  const p2v54RenderReportsBase=p2RenderReports;
  p2RenderReports=function(mode='class'){
    if(mode!=='class'){const poolCard=$('p2ReportSummary')?.closest('.card');if(poolCard)poolCard.style.display='';return p2v54RenderReportsBase(mode)}
    p2ReportMode='class';const panel=$('p2ReportPanel');if(!panel)return;const poolCard=$('p2ReportSummary')?.closest('.card');if(poolCard)poolCard.style.display='none';p2v54ClassReportHome(panel)
  };

  // Keep the Classes home Report tile opening the simplified class-report home.
  if($('p2ClassesReports'))$('p2ClassesReports').onclick=()=>{p2ReportMode='class';switchPage('phase2Reports');p2RenderReports('class')};
'''

html=html.replace(marker,fix+marker)
required=['PHASE2 BETA5 FIX4','Student Progress List','Follow-up & Outreach','Annual Class Summary','Admin approval required','All\',\'Joined\',\'Eligible\',\'Not Eligible','export the filtered Batch Report','p2v54NextStatus']
missing=[x for x in required if x not in html]
if missing: raise SystemExit('Missing beta.5.4 markers: '+repr(missing))
p.write_text(html,encoding='utf-8')
print('BETA5 FIX4 APPLIED',len(html))
